"use client";

import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";

export function PaymentsFilter({
  onChange,
}: {
  onChange: (value: { search: string; status: string; method: string }) => void;
}) {
  return (
    <div className="mt-6 grid gap-3 sm:grid-cols-3">
      <Input
        placeholder="Search transaction or user"
        onChange={(event) =>
          onChange({ search: event.target.value, status: "", method: "" })
        }
      />
      <Select
        aria-label="Payment status"
        onChange={(event) =>
          onChange({ search: "", status: event.target.value, method: "" })
        }
      >
        <option value="">All statuses</option>
        <option value="completed">Completed</option>
        <option value="pending">Pending</option>
        <option value="failed">Failed</option>
      </Select>
      <Select
        aria-label="Payment method"
        onChange={(event) =>
          onChange({ search: "", status: "", method: event.target.value })
        }
      >
        <option value="">All methods</option>
        <option value="bkash">bKash</option>
        <option value="nagad">Nagad</option>
        <option value="bank">Bank</option>
      </Select>
    </div>
  );
}
